import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface ScanRequest extends Request {
  body: {
    jobDescription: string;
  };
  file?: Express.Multer.File;
}

router.post('/api/scan-resume', upload.single('resume'), async (req: ScanRequest, res: Response): Promise<void> => {
  try {
    if (!req.file || !req.body.jobDescription) {
      res.status(400).json({ error: 'Missing resume file or job description' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();
    const jdText = req.body.jobDescription.toLowerCase();

    // Extract unique keywords from job description (simple tokenizer)
    const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'that', 'by', 'this', 'with', 'i', 'you']);
    const jdWords = jdText.match(/\b[a-z]{3,}\b/g) || [];
    const uniqueKeywords = Array.from(new Set(jdWords)).filter(word => !stopWords.has(word));

    const matched: string[] = [];
    const missing: string[] = [];

    uniqueKeywords.forEach(keyword => {
      const regex = new RegExp(`\\b${keyword}\\b`, 'i');
      if (regex.test(resumeText)) {
        matched.push(keyword);
      } else {
        missing.push(keyword);
      }
    });

    const totalKeywords = uniqueKeywords.length;
    const matchScore = totalKeywords > 0 ? Math.round((matched.length / totalKeywords) * 100) : 0;

    res.json({
      matchScore,
      breakdown: {
        matched: matched.slice(0, 25),
        missing: missing.slice(0, 25),
        totalAnalyzed: totalKeywords
      }
    });
  } catch (error) {
    console.error('Scan error:', error);
    res.status(500).json({ error: 'Failed to parse PDF and analyze resume' });
  }
});

export default router;

import React from 'react';

interface ScanResultProps {
  matchScore: number;
  breakdown: {
    matched: string[];
    missing: string[];
    totalAnalyzed: number;
  };
}

export const TailwindMatchScoreGauge: React.FC<ScanResultProps> = ({ matchScore, breakdown }) => {
  const circumference = 2 * Math.PI * 45;
  const strokeDashoffset = circumference - (matchScore / 100) * circumference;

  return (
    <div className="max-w-2xl mx-auto p-6 bg-white rounded-2xl shadow-xl border border-gray-100 space-y-8">
      <div className="flex flex-col sm:flex-row items-center justify-between gap-6">
        <div className="relative flex items-center justify-center">
          <svg className="w-36 h-36 transform -rotate-90">
            <circle
              cx="72"
              cy="72"
              r="45"
              stroke="currentColor"
              strokeWidth="10"
              className="text-gray-100 fill-none"
            />
            <circle
              cx="72"
              cy="72"
              r="45"
              stroke="currentColor"
              strokeWidth="10"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              strokeLinecap="round"
              className="text-indigo-600 fill-none transition-all duration-1000 ease-out"
            />
          </svg>
          <div className="absolute flex flex-col items-center justify-center">
            <span className="text-3xl font-extrabold text-gray-900">{matchScore}%</span>
            <span className="text-xs font-medium text-gray-500 uppercase tracking-wider">Match Score</span>
          </div>
        </div>
        <div className="flex-1 text-center sm:text-left">
          <h3 className="text-xl font-bold text-gray-900">Keyword Analysis Complete</h3>
          <p className="text-sm text-gray-600 mt-1">
            Analyzed {breakdown.totalAnalyzed} key terms against the target job description.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-gray-100">
        <div>
          <h4 className="text-sm font-semibold text-emerald-700 mb-3 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500"></span> Matched Keywords ({breakdown.matched.length})
          </h4>
          <div className="flex flex-wrap gap-1.5">
            {breakdown.matched.map((kw, i) => (
              <span key={i} className="px-2.5 py-1 bg-emerald-50 text-emerald-700 text-xs font-medium rounded-md border border-emerald-200">
                {kw}
              </span>
            ))}
          </div>
        </div>
        <div>
          <h4 className="text-sm font-semibold text-rose-700 mb-3 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-rose-500"></span> Missing Keywords ({breakdown.missing.length})
          </h4>
          <div className="flex flex-wrap gap-1.5">
            {breakdown.missing.map((kw, i) => (
              <span key={i} className="px-2.5 py-1 bg-rose-50 text-rose-700 text-xs font-medium rounded-md border border-rose-200">
                {kw}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};
